14	/// `JSX.IntrinsicElements[element]` in React's own types at `react_file`, when this run has them: Full mode merges them,
15	/// curated mode indexes them apart (`ResolutionContext::react_index`), and `none` mode and the dependency loader don't
16	/// read them.
17	pub(super) fn intrinsic_element<'a>(
18	    element: &str,
19	    react_file: &Utf8Path,
20	    ctx: &'a ResolutionContext,
21	) -> Option<&'a CollectedType> {
22	    let elements = ctx.react_index().lookup_interface_exact(react_file, "React.JSX.IntrinsicElements")?;
23	    Some(&elements.props.iter().find(|prop| prop.name == element)?.collected_type)
24	}
