26	/// React's interface `key` (`React.HTMLAttributes`) followed by the augmentations other files merge into it
27	/// (`NamedTypeIndex::react_augmentations`): the project's and the loaded dependencies' in every mode, since curated mode
28	/// indexes only React's own file apart.
29	fn merged_interfaces<'a>(key: &str, react_file: &Utf8Path, ctx: &'a ResolutionContext) -> Vec<&'a CollectedInterface> {
30	    let mut layers: Vec<&CollectedInterface> =
31	        ctx.react_index().lookup_interface_exact(react_file, key).into_iter().collect();
32	    layers.extend(ctx.named_types.react_augmentations(react_file, key));
33	    layers
34	}
