49	/// The declaration of attribute `name` on intrinsic element `element`, read as TypeScript reads
50	/// `JSX.IntrinsicElements[element]` (`intrinsic_element`). `None` without React's types, or when the element has no such
51	/// attribute.
52	pub(super) fn react_attribute(
53	    element: &str,
54	    name: &str,
55	    react_file: &Utf8Path,
56	    ctx: &ResolutionContext,
57	    state: &mut ResolveState,
58	    depth: u8,
59	) -> Option<ParsedProp> {
60	    // Declared inside `declare namespace React`, so keyed by their qualified names whichever way they are referenced.
61	    let key = |type_name: &str| format!("React.{}", type_name.strip_prefix("React.").unwrap_or(type_name));
62	    let mut pending = VecDeque::from([intrinsic_element(element, react_file, ctx)?.clone()]);
63	    // React's attribute types are a small tree; the bound only guards against a malformed declaration file.
64	    for _ in 0..64 {
65	        match pending.pop_front()? {
66	            CollectedType::AtFile { inner, .. } => pending.push_back(*inner),
67	            CollectedType::Intersection(members) => pending.extend(members),
68	            CollectedType::Named { name: type_name, args } => {
69	                let key = key(&type_name);
70	                // Defaulted parameters (`T = Element`) are not supplied, and need no warning.
71	                let mut ignored = Vec::new();
72	                let layers = merged_interfaces(&key, react_file, ctx);
73	                if !layers.is_empty() {
74	                    for iface in layers {
75	                        let params = index_of(iface, react_file, ctx).lookup_interface_type_params_for(iface);
76	                        let subst = params.map(|params| build_substitution(params, &args, react_file, &mut ignored));
77	                        let substituted =
78	                            |ty: &CollectedType| subst.as_ref().map_or_else(|| ty.clone(), |s| substitute_type(ty, s));
79	                        if let Some(raw) = iface.props.iter().find(|prop| prop.name == name) {
80	                            let ty = substituted(&raw.collected_type);
81	                            let prop_type = resolve_collected_type(&ty, &iface.file_path, ctx, state, depth);
82	                            let parent =
83	                                PropParent { name: iface.name.to_string(), file_name: iface.file_path.to_string() };
84	                            return Some(ParsedProp::new(
85	                                name.to_owned(),
86	                                prop_type,
87	                                raw.required,
88	                                None,
89	                                raw.description.clone(),
90	                                raw.tags.clone(),
91	                                Some(parent.clone()),
92	                                vec![parent],
93	                            ));
94	                        }
95	                        pending.extend(iface.extends.iter().map(|extends| {
96	                            let (ExtendsRef::SameFile { name, type_args }
97	                            | ExtendsRef::Imported { local_name: name, type_args, .. }
98	                            | ExtendsRef::Builtin { name, type_args, .. }) = extends;
99	                            CollectedType::Named {
100	                                name: name.clone(),
101	                                args: type_args.iter().map(substituted).collect(),
102	                            }
103	                        }));
104	                    }
105	                } else if let Some(alias) = ctx.react_index().lookup_type_alias_exact(react_file, &key) {
106	                    let alias = match ctx.react_index().lookup_type_alias_params(react_file, &key) {
107	                        Some(params) => {
108	                            substitute_alias(alias, &build_substitution(params, &args, react_file, &mut ignored))
109	                        }
110	                        None => alias.clone(),
111	                    };
112	                    match alias {
113	                        CollectedTypeAlias::Intersection { members, .. } => pending.extend(members),
114	                        CollectedTypeAlias::Passthrough { target, .. } => pending.push_back(target),
115	                        _ => {}
116	                    }
117	                }
118	            }
119	            _ => {}
120	        }
121	    }
122	    None
123	}
