125	/// Every attribute name `JSX.IntrinsicElements[element]` declares in React's own types at `react_file`, in the order
126	/// `react_attribute` reads them; empty without those types.
127	fn react_attribute_names(element: &str, react_file: &Utf8Path, ctx: &ResolutionContext) -> Vec<String> {
128	    let mut names: Vec<String> = Vec::new();
129	    let Some(root) = intrinsic_element(element, react_file, ctx) else {
130	        return names;
131	    };
132	    let mut pending = VecDeque::from([root.clone()]);
133	    for _ in 0..64 {
134	        let Some(next) = pending.pop_front() else {
135	            break;
136	        };
137	        match next {
138	            CollectedType::AtFile { inner, .. } => pending.push_back(*inner),
139	            CollectedType::Intersection(members) => pending.extend(members),
140	            CollectedType::Named { name: type_name, args } => {
141	                let key = format!("React.{}", type_name.strip_prefix("React.").unwrap_or(&type_name));
142	                let layers = merged_interfaces(&key, react_file, ctx);
143	                if !layers.is_empty() {
144	                    for iface in layers {
145	                        names.extend(iface.props.iter().map(|prop| prop.name.clone()));
146	                        pending.extend(iface.extends.iter().map(|extends| {
147	                            let (ExtendsRef::SameFile { name, type_args }
148	                            | ExtendsRef::Imported { local_name: name, type_args, .. }
149	                            | ExtendsRef::Builtin { name, type_args, .. }) = extends;
150	                            CollectedType::Named { name: name.clone(), args: type_args.clone() }
151	                        }));
152	                    }
153	                } else if let Some(alias) = ctx.react_index().lookup_type_alias_exact(react_file, &key) {
154	                    let alias = match ctx.react_index().lookup_type_alias_params(react_file, &key) {
155	                        Some(params) => {
156	                            substitute_alias(alias, &build_substitution(params, &args, react_file, &mut Vec::new()))
157	                        }
158	                        None => alias.clone(),
159	                    };
160	                    match alias {
161	                        CollectedTypeAlias::Intersection { members, .. } => pending.extend(members),
162	                        CollectedTypeAlias::Passthrough { target, .. } => pending.push_back(target),
163	                        _ => {}
164	                    }
165	                }
166	            }
167	            _ => {}
168	        }
169	    }
170	    let mut seen = rustc_hash::FxHashSet::default();
171	    names.retain(|name| seen.insert(name.clone()));
172	    names
173	}
