175	/// The attributes of an HTML layer's element that `has` doesn't already list: every one `@types/react` declares when
176	/// `full`, else the curated subset (`react_types::is_curated_html_attr`), each as React declares it minus what the layer
177	/// omits. Without React's types the curated table stands in, typed by name.
178	pub(super) fn layer_attributes(
179	    layer: &InheritedLayer,
180	    full: bool,
181	    has: impl Fn(&str) -> bool,
182	    ctx: &ResolutionContext,
183	    state: &mut ResolveState,
184	    depth: u8,
185	) -> Vec<Arc<ParsedProp>> {
186	    let Some(element) = layer.html_element.as_deref() else {
187	        return Vec::new();
188	    };
189	    let file = Utf8Path::new(&layer.file_name);
190	    // `ref` is a prop of `ComponentProps<"div">` (`ClassAttributes`) but not of `HTMLAttributes<HTMLDivElement>`.
191	    let bare = layer.type_name.strip_prefix("React.").unwrap_or(&layer.type_name);
192	    let takes_ref = matches!(bare, "ComponentProps" | "ComponentPropsWithRef");
193	    let key = format!("{}\0{element}\0{full}", layer.file_name);
194	    let cached = ctx.attribute_names.get(&key).map(|names| names.clone());
195	    let names: Arc<[String]> = match cached {
196	        Some(names) => names,
197	        None => {
198	            let declared = react_attribute_names(element, file, ctx);
199	            let names: Vec<String> = match (full, declared.is_empty()) {
200	                (true, false) => declared.into_iter().filter(|name| name != "key").collect(),
201	                (false, false) => declared
202	                    .into_iter()
203	                    .filter(|name| crate::react_types::is_curated_html_attr(element, name))
204	                    .collect(),
205	                (_, true) => Vec::new(),
206	            };
207	            let names: Arc<[String]> = names.into();
208	            ctx.attribute_names.insert(key, names.clone());
209	            names
210	        }
211	    };
212	    let loaded = !names.is_empty();
213	    if full && !loaded {
214	        state.diagnostics.push(
215	            Diagnostic::new(
216	                DiagnosticSeverity::Info,
217	                DiagnosticCode::MissingTypeLibrary,
218	                format!("@types/react could not be resolved, so the attributes of <{element}> are left out"),
219	            )
220	            .with_help("Check that @types/react is installed."),
221	        );
222	        return Vec::new();
223	    }
224	    let names: Vec<String> = if loaded {
225	        names.to_vec()
226	    } else {
227	        crate::react_types::notable_html_attrs(element)
228	            .iter()
229	            .chain(["ref"].iter())
230	            .map(|name| (*name).to_owned())
231	            .collect()
232	    };
233	    let parent = PropParent {
234	        name: format!("{}HTMLAttributes", capitalize_element(element)),
235	        file_name: "node_modules/@types/react/index.d.ts".to_owned(),
236	    };
237	    names
238	        .into_iter()
239	        .filter(|name| (takes_ref || name != "ref") && !has(name) && !layer.omitted.contains(name))
240	        .filter_map(|name| {
241	            if loaded {
242	                return super::alias::layer_attribute(layer, &name, ctx, state, depth).map(|prop| ctx.share(prop));
243	            }
244	            let prop_type = if name == "ref" {
245	                PropType::Named { name: "Ref".into(), args: vec![] }
246	            } else {
247	                infer_html_attr_prop_type(&name)
248	            };
249	            Some(ctx.share(ParsedProp::new(
250	                name,
251	                prop_type,
252	                false,
253	                None,
254	                String::new(),
255	                Default::default(),
256	                Some(parent.clone()),
257	                vec![],
258	            )))
259	        })
260	        .collect()
261	}
