263	pub(super) fn infer_html_attr_prop_type(attr_name: &str) -> PropType {
264	    match attr_name {
265	        "onClick" | "onKeyDown" | "onKeyUp" | "onFocus" | "onBlur" | "onChange" | "onInput" | "onSubmit"
266	        | "onReset" | "onLoad" | "onError" | "onPress" | "onPressStart" | "onPressEnd" | "onHoverStart"
267	        | "onHoverEnd" | "onFocusChange" | "onPressChange" => PropType::Function {
268	            type_params: vec![],
269	            params: vec![FunctionParam::new(Some("e".into()), PropType::Named { name: "Event".into(), args: vec![] })],
270	            return_type: Box::new(PropType::Void),
271	        },
272	        "disabled" | "readOnly" | "required" | "checked" | "multiple" | "noValidate" | "autoFocus" | "fullWidth"
273	        | "loading" | "isDisabled" | "isReadOnly" | "isRequired" => PropType::Boolean,
274	        "tabIndex" | "rows" | "cols" | "maxLength" | "min" | "max" | "width" | "height" | "size" => PropType::Number,
275	        "style" => PropType::CssProperties,
276	        "children" => PropType::ReactNode,
277	        _ => PropType::String,
278	    }
279	}
