    const_arrays: FxHashMap<PathKey, FxHashMap<CompactString, Vec<EnumValue>>>,
    /// Files declaring `React.`-qualified names (`@types/react`), the only ones a qualified fallback can match.
    react_namespaced: FxHashSet<PathKey>,
}

