1044	            exports.push((package, (module.to_owned(), name.to_string(), found)));
1045	        }
1046	    }
1047	    let mut augmenters: Vec<(Box<str>, AugmenterRow)> = Vec::new();
1048	    for item in loader.augmenters.iter() {
1049	        let (module, files): (&str, _) = (std::borrow::Borrow::borrow(item.key()), item.value());
1050	        let Some(dir) = Utf8Path::new(module).parent() else { continue };
1051	        if let Some(package) = entry(dir) {
1052	            augmenters.push((package, (module.to_owned(), files.iter().map(ToString::to_string).collect())));
1053	        }
1054	    }
