1068	        }
1069	    }
1070	    let mut packages: Vec<PackageIndex> = packages.into_values().collect();
1071	    packages.sort_by(|a, b| a.dir.cmp(&b.dir));
1072	    for package in &mut packages {
1073	        package.resolutions.sort();
1074	        package.exports.sort();
1075	        package.augmenters.sort();
